    tasks = observation.get("task", None)
    enemies = observation.get("enemies", [])
    resources = observation.get("resources", [])
    territory = observation.get("territory", {})

    # Helper to clamp within grid
    def clamp(val, lo, hi):
        if val < lo:
            return lo
        if val > hi:
            return hi
        return val

    # Prioritize actions: resource collection > pursuit > territory control
    # Try to move toward nearest resource if available
    if isinstance(resources, list) and resources:
        rx = None
        ry = None
        best_dist = float("inf")
        for r in resources:
            rx_r = r.get("x", 0)
            ry_r = r.get("y", 0)
            dist = abs(rx_r - x) + abs(ry_r - y)
            if dist < best_dist:
                best_dist = dist
                rx, ry = rx_r, ry_r
        if rx is not None:
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            return [dx, dy]

    # If no resources or not reachable, pursue closest enemy if any
    if isinstance(enemies, list) and enemies:
        ex = None
        ey = None
        best_dist = float("inf")
        for e in enemies:
            ex_e = e.get("x", 0)
            ey_e = e.get("y", 0)
            dist = abs(ex_e - x) + abs(ey_e - y)
            if dist < best_dist:
                best_dist = dist
                ex, ey = ex_e, ey_e
        if ex is not None:
            if ex > x:
                dx = 1
            elif ex < x:
                dx = -1
            if ey > y:
                dy = 1
            elif ey < y:
                dy = -1
            return [dx, dy]

    # Territory control: move toward owned/neutral zones if data present
    if isinstance(territory, dict) and territory:
        tx = territory.get("target_x", None)
        ty = territory.get("target_y", None)
        if tx is not None and ty is not None:
            if tx > x:
                dx = 1
            elif tx < x:
                dx = -1
            if ty > y:
                dy = 1
            elif ty < y:
                dy = -1
            return [dx, dy]

    # Fallback: simple exploration within bounds
    # Try to move to a new direction not currently at wall
    if x < width - 1:
        dx = 1
    elif x > 0:
        dx = -1
    if y < height - 1:
        dy = 1
    elif y > 0:
        dy = -1

    return [dx, dy]

